// Combat Intelligence for VIDEO ANALYSIS: the specialist layer (diagnostic patterns, the video
// observation ontology, combat models, technique schemas, drill templates, sport-specific notes)
// that chat does not load. It is far too large for one prompt (~930k chars), so each analysis
// pulls a small, relevant, budgeted set. What is in the pool, and what was held back and why, is
// in knowledge/knowledge-manifest.md (generated by build-combat.mjs).
//
// Selection is deterministic and explainable: every pick carries its score and the reason.

import { COMBAT_NOTES, type CombatNote } from "./combat.generated";
import { estimateTokens } from "./promptBudget";

/** Hard ceiling on Combat Intelligence text added to one analysis prompt. */
export const COMBAT_BUDGET_TOKENS = 6_000;
/** No single note may take more than this many characters (its opening is kept). */
export const COMBAT_NOTE_MAX_CHARS = 2_400;
/** The operating definition is always included, capped tighter. */
const HUB_MAX_CHARS = 1_600;
const MAX_NOTES = 8;

export interface CombatQuery {
  /** sparring | padwork | shadowboxing | drilling | movement | lifting */
  kind: string;
  /** The athlete's primary sport key ("bjj", "boxing", ...) when known. */
  sport?: string | null;
  /** The athlete's requested focus, if any. */
  focus?: string;
  /** Free text describing what was measured (signal labels / details). */
  signalText?: string;
}

export interface CombatPick {
  path: string;
  folder: string;
  title: string;
  score: number;
  reason: string;
  excerpt: string;
  tokens: number;
}

const STOP = new Set([
  "the", "and", "for", "that", "with", "this", "from", "your", "have", "has", "was", "are", "not", "but", "you",
  "into", "when", "what", "how", "its", "can", "will", "all", "any", "one", "two", "per", "off",
]);

function tokenize(s: string): string[] {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .filter((t) => t.length >= 3 && !STOP.has(t));
}

const GRAPPLING_SPORTS = new Set(["bjj", "judo", "wrestling", "mma", "sambo", "grappling"]);
const STRIKING_KINDS = new Set(["padwork", "shadowboxing"]);

/** Which folder is worth how much for this clip. Practical-feedback folders lead. */
function folderWeight(note: CombatNote, q: CombatQuery): number {
  const sport = (q.sport ?? "").toLowerCase();
  const grappler = GRAPPLING_SPORTS.has(sport);
  switch (note.folder) {
    case "Video Observation Ontology":
      return 1.5;
    case "Diagnostic Patterns":
      return 1.4;
    case "Drill Templates":
      return 1.4;
    case "Combat Models":
      return 1.0;
    case "Universal Concepts":
      return 1.0;
    case "Technique Schemas":
      return grappler && !STRIKING_KINDS.has(q.kind) ? 0.9 : 0.35;
    case "BJJ Intelligence":
      return grappler && !STRIKING_KINDS.has(q.kind) ? 0.9 : 0.15;
    default:
      return 0.8;
  }
}

const LONG_NOTE_CHARS = 6_000;

interface Indexed {
  note: CombatNote;
  titleTokens: string[];
  bodyLower: string;
}

let INDEX: Indexed[] | null = null;
function index(): Indexed[] {
  if (INDEX) return INDEX;
  INDEX = COMBAT_NOTES.map((note) => ({ note, titleTokens: tokenize(note.title), bodyLower: note.body.toLowerCase() }));
  return INDEX;
}

/** Cut at a paragraph (else sentence, else word) boundary at or before `cap`. */
export function headOfNote(text: string, cap: number): string {
  if (text.length <= cap) return text;
  const window = text.slice(0, cap);
  let cut = window.lastIndexOf("\n\n");
  if (cut < cap * 0.5) cut = Math.max(window.lastIndexOf(". "), window.lastIndexOf("\n"));
  if (cut < cap * 0.5) cut = window.lastIndexOf(" ");
  return window.slice(0, cut > 0 ? cut : cap).trimEnd();
}

/**
 * Pick the Combat Intelligence notes most useful for this clip, within the token budget.
 * Pure (no I/O); the same query always yields the same picks.
 */
export function selectCombatNotes(q: CombatQuery, opts: { budgetTokens?: number; maxNotes?: number } = {}): CombatPick[] {
  const budgetChars = (opts.budgetTokens ?? COMBAT_BUDGET_TOKENS) * 4;
  const maxNotes = opts.maxNotes ?? MAX_NOTES;
  const picks: CombatPick[] = [];
  let used = 0;

  // 1) The operating definition: what Combat Intelligence is and how to use it. Always, kept short.
  const hub = index().find((i) => i.note.folder === "Combat Intelligence Hub" && /operating definition/i.test(i.note.title));
  if (hub) {
    const excerpt = headOfNote(hub.note.body, HUB_MAX_CHARS);
    picks.push({ path: hub.note.path, folder: hub.note.folder, title: hub.note.title, score: 1000, reason: "operating definition (always)", excerpt, tokens: estimateTokens(excerpt.length) });
    used += excerpt.length;
  }

  const query = [q.kind, q.sport ?? "", q.focus ?? "", q.signalText ?? ""].join(" ");
  const qFreq = new Map<string, number>();
  for (const t of tokenize(query)) qFreq.set(t, (qFreq.get(t) ?? 0) + 1);
  // The clip kind and sport count extra: they are the strongest statement of what to look for.
  for (const t of tokenize(`${q.kind} ${q.sport ?? ""}`)) qFreq.set(t, (qFreq.get(t) ?? 0) + 2);
  if (qFreq.size === 0) return picks;

  const scored: { i: Indexed; score: number; reason: string }[] = [];
  for (const i of index()) {
    if (i === hub) continue;
    let titleHits = 0;
    for (const tt of i.titleTokens) titleHits += qFreq.get(tt) ?? 0;
    let bodyHits = 0;
    for (const [tok, f] of qFreq) {
      if (tok.length < 4) continue;
      let idx = i.bodyLower.indexOf(tok);
      let c = 0;
      while (idx !== -1 && c < 4) {
        c++;
        idx = i.bodyLower.indexOf(tok, idx + tok.length);
      }
      bodyHits += c * f;
    }
    // A very long note matches nearly everything on word count alone: damp it.
    bodyHits /= Math.max(1, Math.sqrt(i.bodyLower.length / LONG_NOTE_CHARS));
    const raw = titleHits * 8 + bodyHits;
    if (raw <= 0) continue;
    const score = raw * folderWeight(i.note, q);
    scored.push({ i, score, reason: titleHits > 0 ? `title match (${titleHits})` : "content match" });
  }
  scored.sort((a, b) => b.score - a.score || a.i.note.path.localeCompare(b.i.note.path));

  // 2) Fill the budget best-first, with a cap per folder so one folder cannot crowd out the rest.
  const perFolder = new Map<string, number>();
  const FOLDER_CAP = new Map([["Drill Templates", 2], ["Diagnostic Patterns", 3], ["Video Observation Ontology", 2]]);
  for (const s of scored) {
    if (picks.length >= maxNotes) break;
    const cap = FOLDER_CAP.get(s.i.note.folder) ?? 2;
    if ((perFolder.get(s.i.note.folder) ?? 0) >= cap) continue;
    const room = budgetChars - used;
    if (room < 700) break;
    const excerpt = headOfNote(s.i.note.body, Math.min(COMBAT_NOTE_MAX_CHARS, room));
    if (excerpt.length < 200) continue;
    picks.push({
      path: s.i.note.path,
      folder: s.i.note.folder,
      title: s.i.note.title,
      score: Math.round(s.score * 10) / 10,
      reason: s.reason,
      excerpt,
      tokens: estimateTokens(excerpt.length),
    });
    used += excerpt.length;
    perFolder.set(s.i.note.folder, (perFolder.get(s.i.note.folder) ?? 0) + 1);
  }
  return picks;
}

/** The prompt block for a set of picks. Empty string when there are none. */
export function combatContextBlock(picks: readonly CombatPick[]): string {
  if (picks.length === 0) return "";
  const body = picks.map((p) => `### ${p.title}  (${p.folder})\n\n${p.excerpt}`).join("\n\n---\n\n");
  return [
    "# Combat Intelligence — specialist reference for reading this clip",
    "",
    "Use these notes to decide WHAT to look for and WHAT to prescribe. They are reference, not the athlete's footage: never claim the clip shows something only because a note describes it, keep observation (what is visible) separate from interpretation (what it likely costs), and prefer the drills and constraints they describe for the \"fix\" of each finding.",
    "",
    body,
  ].join("\n");
}

export function combatPickTokens(picks: readonly CombatPick[]): number {
  return picks.reduce((n, p) => n + p.tokens, 0);
}
